package com.ebuddy.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*;
@Service public class JwtService { private final SecretKey key; private final Duration ttl; public JwtService(@Value("${ebuddy.jwt.secret}")String secret,@Value("${ebuddy.jwt.ttl}")Duration ttl){if(secret.getBytes(StandardCharsets.UTF_8).length<32)throw new IllegalArgumentException("JWT secret must be at least 256 bits");key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.ttl=ttl;} public String create(UUID user){Instant now=Instant.now();return Jwts.builder().subject(user.toString()).issuedAt(Date.from(now)).expiration(Date.from(now.plus(ttl))).signWith(key).compact();} public UUID subject(String token){return UUID.fromString(Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject());} public Instant expires(){return Instant.now().plus(ttl);} }
